create type public.app_role as enum ('admin','user');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role public.app_role not null, unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create policy "Own roles" on public.user_roles for select to authenticated using(user_id=auth.uid());
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
revoke all on function public.has_role(uuid,public.app_role) from public; grant execute on function public.has_role(uuid,public.app_role) to authenticated;
insert into public.user_roles(user_id,role) select id,'admin' from auth.users where id='98ac820b-9858-4a8b-b8f5-3f0ed4990cb0' and lower(email)='niramayacare01@gmail.com' and email_confirmed_at is not null;
create table public.subscription_plans (id text primary key, name text not null, description text not null, price_year integer not null, price_two_year integer not null, enabled boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select on public.subscription_plans to anon,authenticated; grant all on public.subscription_plans to service_role;
alter table public.subscription_plans enable row level security;
create policy "Visible plans" on public.subscription_plans for select to anon,authenticated using(enabled);
insert into public.subscription_plans(id,name,description,price_year,price_two_year) values ('base','Elixir Base','Preclinical + paraclinical subjects',149900,249900),('catalyst','Elixir Catalyst','Clinical subjects',249900,399900),('panacea','Elixir Panacea','The whole question bank',399900,599900);
create table public.plan_subjects(plan_id text references public.subscription_plans(id) not null,subject text not null,primary key(plan_id,subject));
grant select on public.plan_subjects to anon,authenticated; grant all on public.plan_subjects to service_role;
alter table public.plan_subjects enable row level security;
create policy "Plan coverage" on public.plan_subjects for select to anon,authenticated using(true);
insert into public.plan_subjects select 'panacea',subject from public.questions group by subject;
insert into public.plan_subjects select 'base',subject from public.questions where subject in ('Anatomy','Physiology','Biochemistry','Pathology','Pharmacology','Microbiology','PSM','FMT') group by subject;
insert into public.plan_subjects select 'catalyst',subject from public.questions where subject not in ('Anatomy','Physiology','Biochemistry','Pathology','Pharmacology','Microbiology','PSM','FMT') group by subject;
create table public.discount_coupons(code text primary key,percent integer not null,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select,insert,update on public.discount_coupons to authenticated; grant all on public.discount_coupons to service_role;
alter table public.discount_coupons enable row level security;
create policy "Admin coupons" on public.discount_coupons for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.payment_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,plan_id text not null references public.subscription_plans(id),months integer not null,total_paise integer not null,coupon_code text,discount_percent integer not null default 0,payment_reference text not null,status text not null default 'pending',approved_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select on public.payment_requests to authenticated; grant all on public.payment_requests to service_role;
alter table public.payment_requests enable row level security;
create policy "Own or admin payments" on public.payment_requests for select to authenticated using(user_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,plan_id text not null references public.subscription_plans(id),starts_at timestamptz not null,ends_at timestamptz not null,payment_request_id uuid unique references public.payment_requests(id),approved_by uuid not null,revoked boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select on public.subscriptions to authenticated; grant all on public.subscriptions to service_role;
alter table public.subscriptions enable row level security;
create policy "Own or admin subscriptions" on public.subscriptions for select to authenticated using(user_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create function public.subscription_validate() returns trigger language plpgsql set search_path=public as $$ begin
new.updated_at=now();
if tg_table_name='discount_coupons' then new.code=upper(btrim(new.code)); if new.percent<1 or new.percent>100 or new.code !~ '^[A-Z0-9_-]{3,32}$' then raise exception 'Use a 3–32 character code and a discount from 1 to 100 percent'; end if;
elsif tg_table_name='subscriptions' then if new.ends_at<=new.starts_at then raise exception 'End date must follow start date'; end if;
elsif tg_table_name='payment_requests' then if new.months<1 or new.months>36 or new.total_paise<0 or new.status not in ('pending','approved','rejected') then raise exception 'Invalid payment request'; end if; end if; return new; end $$;
create trigger coupons_validate before insert or update on public.discount_coupons for each row execute function public.subscription_validate();
create trigger subscriptions_validate before insert or update on public.subscriptions for each row execute function public.subscription_validate();
create trigger payments_validate before insert or update on public.payment_requests for each row execute function public.subscription_validate();
create trigger plans_updated before update on public.subscription_plans for each row execute function public.subscription_validate();
create function public.quote_plan(_plan text,_months integer,_coupon text default '') returns table(total_paise integer,discount_percent integer) language plpgsql security definer set search_path=public as $$ declare p public.subscription_plans; d integer=0; amount integer; begin
if auth.uid() is null then raise exception 'Sign in to select a plan'; end if;
select * into p from public.subscription_plans where id=_plan and enabled; if not found or _months not in (12,24) then raise exception 'Choose a valid plan and duration'; end if;
if btrim(_coupon)<>'' then select percent into d from public.discount_coupons where code=upper(btrim(_coupon)) and enabled; if not found then raise exception 'Coupon unavailable'; end if; end if;
amount=case when _months=12 then p.price_year else p.price_two_year end; return query select round(amount*(100-d)/100.0)::int,d; end $$;
create function public.submit_payment_request(_plan text,_months integer,_coupon text,_reference text) returns uuid language plpgsql security definer set search_path=public as $$ declare q record; rid uuid; begin
if auth.uid() is null then raise exception 'Sign in first'; end if;
if length(btrim(_reference))<3 or length(_reference)>150 then raise exception 'Enter a valid payment reference'; end if;
select * into q from public.quote_plan(_plan,_months,_coupon);
if exists(select 1 from public.payment_requests where user_id=auth.uid() and status='pending' and plan_id=_plan) then raise exception 'Your payment is already awaiting verification'; end if;
insert into public.payment_requests(user_id,plan_id,months,total_paise,coupon_code,discount_percent,payment_reference) values(auth.uid(),_plan,_months,q.total_paise,nullif(upper(btrim(_coupon)),''),q.discount_percent,btrim(_reference)) returning id into rid; return rid; end $$;
create function public.admin_students(_search text default '',_offset integer default 0) returns table(user_id uuid,email text,full_name text,study_year text,college text) language plpgsql security definer set search_path=public as $$ begin
if not public.has_role(auth.uid(),'admin') then raise exception 'Administrator access required'; end if;
return query select p.id,u.email::text,p.full_name,p.study_year,p.college from public.profiles p join auth.users u on u.id=p.id where concat(u.email,' ',p.full_name) ilike '%'||left(_search,100)||'%' order by p.created_at desc limit 50 offset greatest(_offset,0); end $$;
create function public.approve_subscription(_user uuid,_plan text,_months integer,_start date,_request uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare r public.payment_requests; sid uuid; begin
if not public.has_role(auth.uid(),'admin') then raise exception 'Administrator access required'; end if;
if _months not between 1 and 36 or _start is null then raise exception 'Choose 1–36 months and a start date'; end if;
if _request is not null then select * into r from public.payment_requests where id=_request for update; if not found or r.status<>'pending' or r.user_id<>_user or r.plan_id<>_plan then raise exception 'Request is unavailable or already processed'; end if; end if;
insert into public.subscriptions(user_id,plan_id,starts_at,ends_at,approved_by,payment_request_id) values(_user,_plan,_start::timestamptz,_start::timestamptz+make_interval(months=>_months),auth.uid(),_request) returning id into sid;
if _request is not null then update public.payment_requests set status='approved',approved_by=auth.uid() where id=_request; end if; return sid; end $$;
create function public.reject_payment(_request uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not public.has_role(auth.uid(),'admin') then raise exception 'Administrator access required'; end if; update public.payment_requests set status='rejected',approved_by=auth.uid() where id=_request and status='pending'; end $$;
create function public.revoke_subscription(_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not public.has_role(auth.uid(),'admin') then raise exception 'Administrator access required'; end if; update public.subscriptions set revoked=true where id=_id; end $$;
revoke all on function public.quote_plan(text,integer,text),public.submit_payment_request(text,integer,text,text),public.admin_students(text,integer),public.approve_subscription(uuid,text,integer,date,uuid),public.reject_payment(uuid),public.revoke_subscription(uuid) from public;
grant execute on function public.quote_plan(text,integer,text),public.submit_payment_request(text,integer,text,text),public.admin_students(text,integer),public.approve_subscription(uuid,text,integer,date,uuid),public.reject_payment(uuid),public.revoke_subscription(uuid) to authenticated;
alter table public.questions add column is_free boolean not null default false;
create function public.refresh_free_questions() returns void language sql security definer set search_path=public as $$ update public.questions q set is_free=r.rn<=floor(r.total*0.10) from (select id,row_number() over(partition by subject order by sort_key,id) rn,count(*) over(partition by subject) total from public.questions) r where q.id=r.id $$;
revoke all on function public.refresh_free_questions() from public; grant execute on function public.refresh_free_questions() to service_role;
select public.refresh_free_questions();
create function public.has_subject_access(_subject text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.subscriptions s join public.plan_subjects ps on ps.plan_id=s.plan_id where s.user_id=auth.uid() and ps.subject=_subject and not s.revoked and s.starts_at<=now() and s.ends_at>now()) $$;
revoke all on function public.has_subject_access(text) from public; grant execute on function public.has_subject_access(text) to anon,authenticated;
drop policy "Questions are public" on public.questions;
create policy "Free sample or active subscription" on public.questions for select to anon,authenticated using(is_free or public.has_subject_access(subject));